+package semver
+
+import "testing"
+
+// Regression: a range whose upper bound is a dirty version (e.g. 4.5) must
+// accept versions with a lower major regardless of their minor/patch.
+func TestConstraintDirtyRangeUpperBound(t *testing.T) {
+	tests := []struct {
+		constraint string
+		version    string
+		check      bool
+	}{
+		{"1.5.0 - 4.5", "3.7.0", true},
+		{"1.5.0 - 4.5", "4.5.9", true},
+		{"1.5.0 - 4.5", "4.6.0", false},
+		{"1.5.0 - 4.5", "5.0.0", false},
+		{"1.5.0 - 4.5", "1.5.0", true},
+		{"1.5.0 - 4.5", "1.4.9", false},
+		{"<=4.5", "3.7.0", true},
+		{"<=4.5", "4.6.0", false},
+	}
+
+	for _, tc := range tests {
+		c, err := NewConstraint(tc.constraint)
+		if err != nil {
+			t.Fatalf("err: %s", err)
+		}
+		v, err := NewVersion(tc.version)
+		if err != nil {
+			t.Fatalf("err: %s", err)
+		}
+		if got := c.Check(v); got != tc.check {
+			t.Errorf("Constraint '%s' with '%s': got %v, want %v", tc.constraint, tc.version, got, tc.check)
+		}
+	}
+}

