--- /dev/null
+++ b/constraints_segment_test.go
@@ -0,0 +1,33 @@
+package semver
+
+import "testing"
+
+func TestNewConstraintRejectsSplitVersionSegments(t *testing.T) {
+	invalid := []string{
+		"12.3.4.1234",
+		"12.23.4.1234",
+		"12.3.34.1234",
+	}
+
+	for _, c := range invalid {
+		if _, err := NewConstraint(c); err == nil {
+			t.Errorf("expected NewConstraint(%q) to fail, but it succeeded", c)
+		}
+	}
+
+	valid := map[string]string{
+		"2.x,   >=1.2.3 || >4.5.6, < 5.7": "2.x >=1.2.3 || >4.5.6 <5.7",
+		"1.2.3 2.3.4":                     "1.2.3 2.3.4",
+	}
+
+	for c, want := range valid {
+		con, err := NewConstraint(c)
+		if err != nil {
+			t.Errorf("expected NewConstraint(%q) to succeed, got err: %s", c, err)
+			continue
+		}
+		if got := con.String(); got != want {
+			t.Errorf("NewConstraint(%q).String() = %q, want %q", c, got, want)
+		}
+	}
+}
